"use client";

import Link from "next/link";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { KeyRound } from "lucide-react";
import { toast } from "sonner";
import { z } from "zod";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { resetPasswordAction } from "@/features/auth/actions";
import { siteConfig } from "@/config/site";

const forgotPasswordSchema = z.object({
  identifier: z.string().min(1, "Student/Employee ID is required"),
});

export default function ForgotPasswordPage() {
  const form = useForm<z.infer<typeof forgotPasswordSchema>>({
    resolver: zodResolver(forgotPasswordSchema),
    defaultValues: {
      identifier: "",
    },
  });

  async function onSubmit(values: z.infer<typeof forgotPasswordSchema>) {
    const result = await resetPasswordAction(values.identifier);
    if (result.error) {
      toast.error(result.error);
    } else {
      toast.success("If an account exists, a reset link has been sent to your registered email.");
      form.reset();
    }
  }

  return (
    <Card className="border-border/60 shadow-lg">
      <CardHeader className="space-y-4">
        <div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-primary text-primary-foreground">
          <KeyRound className="h-5 w-5" />
        </div>
        <div className="space-y-1">
          <CardTitle className="text-2xl">Forgot Password</CardTitle>
          <CardDescription>
            Enter your Student ID or Employee ID. We will send a password reset link to your registered email address.
          </CardDescription>
        </div>
      </CardHeader>
      <CardContent>
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            <FormField
              control={form.control}
              name="identifier"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Student / Employee ID</FormLabel>
                  <FormControl>
                    <Input
                      placeholder="e.g. STU2024001"
                      autoComplete="username"
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <Button
              type="submit"
              className="w-full rounded-xl"
              disabled={form.formState.isSubmitting}
            >
              {form.formState.isSubmitting ? "Sending link..." : "Send Reset Link"}
            </Button>
          </form>
        </Form>
        <p className="mt-6 text-center text-sm text-muted-foreground">
          Remember your password?{" "}
          <Link href="/login" className="text-primary hover:underline">
            Back to login
          </Link>
        </p>
      </CardContent>
    </Card>
  );
}

"use client";

import { useEffect, useState } from "react";
import { getAdminAnalytics } from "@/features/analytics/actions";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Users, GraduationCap, Building2, TrendingUp, IndianRupee,
  ClipboardList, Award
} from "lucide-react";
import {
  Bar, BarChart, XAxis, YAxis, CartesianGrid, ResponsiveContainer,
  PieChart, Pie, Cell, LineChart, Line, Legend, Tooltip
} from "recharts";
import { ChartContainer, ChartTooltip, ChartTooltipContent, ChartConfig } from "@/components/ui/chart";
import { Skeleton } from "@/components/ui/skeleton";

const COLORS = ["#0ea5e9", "#8b5cf6", "#10b981", "#f59e0b", "#ef4444"];

const chartConfig: ChartConfig = {
  count: { label: "Students", color: "#0ea5e9" },
  value: { label: "Applications", color: "#8b5cf6" },
  revenue: { label: "Revenue (₹)", color: "#10b981" },
};

function MetricSkeleton() {
  return (
    <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6">
      {Array.from({ length: 6 }).map((_, i) => (
        <Card key={i}>
          <CardHeader className="pb-2">
            <Skeleton className="h-4 w-24" />
          </CardHeader>
          <CardContent>
            <Skeleton className="h-8 w-16" />
          </CardContent>
        </Card>
      ))}
    </div>
  );
}

export function AdminDashboardClient() {
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getAdminAnalytics().then(res => {
      setData(res);
      setLoading(false);
    });
  }, []);

  if (loading) {
    return (
      <div className="space-y-6">
        <MetricSkeleton />
        <div className="grid gap-6 md:grid-cols-2">
          <Card><CardContent className="h-[340px]"><Skeleton className="h-full w-full mt-6" /></CardContent></Card>
          <Card><CardContent className="h-[340px]"><Skeleton className="h-full w-full mt-6" /></CardContent></Card>
        </div>
      </div>
    );
  }

  const { metrics, charts } = data;

  const placementPct = metrics.totalStudents > 0
    ? Math.round(
        ((charts.placementData.find((d: any) => d.status === "Selected")?.value || 0) / metrics.totalStudents) * 100
      )
    : 0;

  const metricCards = [
    { label: "Total Students", value: metrics.totalStudents, sub: "Enrolled college-wide", icon: GraduationCap, color: "text-blue-500" },
    { label: "Total Faculty", value: metrics.totalFaculty, sub: "Active staff members", icon: Users, color: "text-purple-500" },
    { label: "Departments", value: metrics.totalDepartments, sub: "Academic departments", icon: Building2, color: "text-green-500" },
    { label: "Avg Attendance", value: `${metrics.overallAttendance}%`, sub: "College-wide average", icon: TrendingUp, color: "text-amber-500" },
    { label: "Assignments", value: metrics.totalAssignments, sub: "Total issued", icon: ClipboardList, color: "text-rose-500" },
    { label: "Placement %", value: `${placementPct}%`, sub: "Students with offers", icon: Award, color: "text-emerald-500" },
  ];

  return (
    <div className="space-y-6">
      {/* KPI Cards */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6">
        {metricCards.map((card) => (
          <Card key={card.label} className="hover:shadow-md transition-shadow">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-xs font-medium text-muted-foreground">{card.label}</CardTitle>
              <card.icon className={`h-4 w-4 ${card.color}`} />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{card.value}</div>
              <p className="text-xs text-muted-foreground mt-1">{card.sub}</p>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Row 1: Students by Dept + Placement Overview */}
      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-7">
        <Card className="col-span-4">
          <CardHeader>
            <CardTitle>Students by Department</CardTitle>
            <CardDescription>Enrollment distribution across all departments.</CardDescription>
          </CardHeader>
          <CardContent>
            {charts.studentsByDept.length > 0 ? (
              <ChartContainer config={chartConfig} className="h-[300px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={charts.studentsByDept} margin={{ top: 10, right: 10, left: 0, bottom: 20 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} className="stroke-muted" />
                    <XAxis dataKey="name" tickLine={false} axisLine={false} className="text-xs" />
                    <YAxis tickLine={false} axisLine={false} className="text-xs" />
                    <ChartTooltip content={<ChartTooltipContent />} />
                    <Bar dataKey="count" fill="#0ea5e9" radius={[4, 4, 0, 0]} name="Students" />
                  </BarChart>
                </ResponsiveContainer>
              </ChartContainer>
            ) : (
              <div className="h-[300px] flex items-center justify-center text-muted-foreground">
                No department data available yet.
              </div>
            )}
          </CardContent>
        </Card>

        <Card className="col-span-3">
          <CardHeader>
            <CardTitle>Placement Overview</CardTitle>
            <CardDescription>Application status distribution across all drives.</CardDescription>
          </CardHeader>
          <CardContent>
            {charts.placementData.length > 0 ? (
              <ChartContainer config={chartConfig} className="h-[300px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={charts.placementData}
                      cx="50%"
                      cy="45%"
                      innerRadius={60}
                      outerRadius={100}
                      paddingAngle={3}
                      dataKey="value"
                      nameKey="status"
                    >
                      {charts.placementData.map((entry: any, index: number) => (
                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip formatter={(v: any, name: any) => [v, name]} />
                    <Legend />
                  </PieChart>
                </ResponsiveContainer>
              </ChartContainer>
            ) : (
              <div className="h-[300px] flex items-center justify-center text-muted-foreground">
                No placement data yet.
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Row 2: Revenue Trend (full width) */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="flex items-center gap-2">
                <IndianRupee className="h-4 w-4 text-emerald-500" />
                Fee Revenue Forecast
              </CardTitle>
              <CardDescription>Projected revenue collection over the last 6 months (illustrative).</CardDescription>
            </div>
            <div className="text-right">
              <p className="text-2xl font-bold">₹{(metrics.totalRevenue / 100000).toFixed(1)}L</p>
              <p className="text-xs text-muted-foreground">6-month total</p>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <ChartContainer config={chartConfig} className="h-[280px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={charts.revenueData} margin={{ top: 10, right: 20, left: 10, bottom: 10 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} className="stroke-muted" />
                <XAxis dataKey="month" tickLine={false} axisLine={false} className="text-xs" />
                <YAxis
                  tickLine={false}
                  axisLine={false}
                  className="text-xs"
                  tickFormatter={(v) => `₹${(v / 100000).toFixed(1)}L`}
                />
                <ChartTooltip
                  content={<ChartTooltipContent formatter={(v: any) => [`₹${(v / 100000).toFixed(2)}L`, "Revenue"]} />}
                />
                <Line
                  type="monotone"
                  dataKey="revenue"
                  stroke="#10b981"
                  strokeWidth={2.5}
                  dot={{ r: 5, fill: "#10b981" }}
                  activeDot={{ r: 7 }}
                />
              </LineChart>
            </ResponsiveContainer>
          </ChartContainer>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { File, Image as ImageIcon, Link as LinkIcon, FileText, PlayCircle, FileArchive, Download, Search, ExternalLink, Trash2 } from "lucide-react";
import { format, parseISO } from "date-fns";
import { toast } from "sonner";
import { deleteNote } from "@/features/notes/actions";

export function AdminNotesClient({ initialNotes }: { initialNotes: any[] }) {
  const [notes, setNotes] = useState(initialNotes);
  const [search, setSearch] = useState("");
  const [facultyFilter, setFacultyFilter] = useState("");

  const faculties = Array.from(new Set(initialNotes.map(n => n.faculty_name))).filter(Boolean);

  const filteredNotes = notes.filter(n => {
    const matchesSearch = n.title.toLowerCase().includes(search.toLowerCase()) || 
                          (n.subject_name && n.subject_name.toLowerCase().includes(search.toLowerCase()));
    const matchesFaculty = facultyFilter ? n.faculty_name === facultyFilter : true;
    return matchesSearch && matchesFaculty;
  });

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to forcibly delete this material? This cannot be undone.")) return;
    const result = await deleteNote(id);
    if (result.error) {
      toast.error(result.error);
    } else {
      toast.success("Material deleted permanently");
      setNotes(notes.filter(n => n.id !== id));
    }
  };

  const getIcon = (type: string) => {
    switch (type) {
      case "pdf": return <FileText className="h-5 w-5 text-red-500" />;
      case "ppt": return <File className="h-5 w-5 text-orange-500" />;
      case "docx": return <FileText className="h-5 w-5 text-blue-500" />;
      case "zip": return <FileArchive className="h-5 w-5 text-yellow-500" />;
      case "image": return <ImageIcon className="h-5 w-5 text-green-500" />;
      case "youtube": return <PlayCircle className="h-5 w-5 text-red-600" />;
      default: return <LinkIcon className="h-5 w-5 text-blue-400" />;
    }
  };

  return (
    <div className="space-y-6">
      <Card>
        <CardContent className="pt-6">
          <div className="flex flex-col md:flex-row gap-4">
            <div className="relative flex-1">
              <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search materials by title or subject..."
                className="pl-8"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
            <div className="w-full md:w-[250px]">
              <select 
                value={facultyFilter} 
                onChange={e => setFacultyFilter(e.target.value)}
                className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
              >
                <option value="">All Faculty</option>
                {faculties.map((f: any) => (
                  <option key={f} value={f}>{f}</option>
                ))}
              </select>
            </div>
          </div>
        </CardContent>
      </Card>

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
        {filteredNotes.map(note => (
          <Card key={note.id} className="flex flex-col h-full">
            <CardContent className="p-5 flex flex-col flex-1">
              <div className="flex justify-between items-start mb-3">
                <div className="flex items-center gap-2 bg-muted px-2 py-1 rounded-md text-xs font-semibold uppercase">
                  {getIcon(note.resource_type)}
                  <span>{note.resource_type}</span>
                </div>
                {note.unit && <Badge variant="outline">{note.unit}</Badge>}
              </div>

              <h3 className="font-bold text-lg leading-tight mb-1 line-clamp-2" title={note.title}>{note.title}</h3>
              <div className="text-xs font-medium text-primary mb-2">{note.subject_code} - {note.subject_name}</div>

              <div className="mt-auto pt-4 flex items-center justify-between border-t border-border/50">
                <div className="flex flex-col">
                  <span className="text-[10px] font-bold uppercase text-muted-foreground">{note.faculty_name}</span>
                  <span className="text-xs text-muted-foreground">{format(parseISO(note.created_at), "MMM d, yyyy")}</span>
                </div>
                <div className="flex gap-2">
                  <a href={note.url} target="_blank" rel="noreferrer" className="inline-flex items-center justify-center rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring hover:bg-accent hover:text-accent-foreground h-8 w-8">
                    <ExternalLink className="h-4 w-4" />
                  </a>
                  <button onClick={() => handleDelete(note.id)} className="inline-flex items-center justify-center rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring hover:bg-destructive/10 text-destructive h-8 w-8">
                    <Trash2 className="h-4 w-4" />
                  </button>
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

import { getUserProfile } from "@/features/auth/user";
import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { AdminNotesClient } from "./client";

export default async function AdminNotesPage() {
  const profile = await getUserProfile();
  if (!profile || profile.role !== "admin") {
    redirect("/login");
  }

  const supabase = await createClient();
  const { data: notes, error } = await supabase
    .from("notes")
    .select(`
      id,
      title,
      description,
      unit,
      resource_type,
      url,
      created_at,
      subjects (
        name,
        code
      ),
      faculty (
        profiles (
          full_name
        )
      )
    `)
    .eq("is_archived", false)
    .order("created_at", { ascending: false });

  if (error) {
    return <div className="p-8 text-destructive">Failed to load study materials.</div>;
  }

  const mapped = (notes as any[]).map(n => ({
    id: n.id,
    title: n.title,
    description: n.description,
    unit: n.unit,
    resource_type: n.resource_type,
    url: n.url,
    created_at: n.created_at,
    subject_name: n.subjects?.name,
    subject_code: n.subjects?.code,
    faculty_name: n.faculty?.profiles?.full_name || "Unknown Faculty",
  }));

  return (
    <div className="flex-1 space-y-6 p-4 md:p-8 pt-6 pb-24">
      <div className="flex flex-col gap-2">
        <h1 className="text-3xl font-bold tracking-tight">Manage Study Materials</h1>
        <p className="text-muted-foreground">Oversight of all uploaded resources across the college.</p>
      </div>

      <AdminNotesClient initialNotes={mapped} />
    </div>
  );
}

"use client";

import { useState } from "react";
import { DataTable } from "@/components/data-table/data-table";
import { getColumns } from "./columns";
import { StudentForm } from "./form";
import { Button } from "@/components/ui/button";
import { Plus } from "lucide-react";

export function StudentsClient({ data, departments, semesters, sections }: any) {
  const [isFormOpen, setIsFormOpen] = useState(false);

  const columns = getColumns();

  return (
    <>
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Students</h1>
          <p className="text-muted-foreground">Manage student accounts and enrollments.</p>
        </div>
        <Button onClick={() => setIsFormOpen(true)}>
          <Plus className="mr-2 h-4 w-4" /> Add Student
        </Button>
      </div>

      <DataTable 
        columns={columns} 
        data={data} 
        searchKey="full_name" 
        searchPlaceholder="Search students..." 
        emptyTitle="No students found" 
      />

      <StudentForm 
        open={isFormOpen} 
        onOpenChange={setIsFormOpen} 
        departments={departments}
        semesters={semesters}
        sections={sections}
      />
    </>
  );
}

"use client";

import type { ColumnDef } from "@tanstack/react-table";
import { Button } from "@/components/ui/button";
import { MoreHorizontal, PowerOff, Trash, Key } from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Badge } from "@/components/ui/badge";
import { toggleUserStatus, deleteUserAccount, resetUserPassword } from "@/features/admin/user-actions";
import { toast } from "sonner";

export const getColumns = (): ColumnDef<any>[] => [
  {
    accessorKey: "full_name",
    header: "Full Name",
  },
  {
    accessorKey: "students.roll_number",
    header: "Roll Number",
    cell: ({ row }) => <span className="font-semibold">{row.original.students.roll_number}</span>
  },
  {
    accessorKey: "email",
    header: "Email",
  },
  {
    accessorKey: "is_active",
    header: "Status",
    cell: ({ row }) => (
      <Badge variant={row.original.is_active ? "default" : "secondary"}>
        {row.original.is_active ? "Active" : "Inactive"}
      </Badge>
    ),
  },
  {
    id: "actions",
    cell: ({ row }) => {
      const user = row.original;

      const handleToggleStatus = async () => {
        const result = await toggleUserStatus(user.id, user.is_active);
        if (result.error) toast.error(result.error);
        else toast.success(`User ${user.is_active ? "deactivated" : "activated"}.`);
      };

      const handleDelete = async () => {
        if (!confirm("Are you sure you want to permanently delete this user?")) return;
        const result = await deleteUserAccount(user.id);
        if (result.error) toast.error(result.error);
        else toast.success("User deleted permanently.");
      };

      const handleResetPassword = async () => {
        if (!confirm("Reset password to 'Welcome@2024'?")) return;
        const result = await resetUserPassword(user.id);
        if (result.error) toast.error(result.error);
        else toast.success("Password reset successfully.");
      };

      return (
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="ghost" className="h-8 w-8 p-0">
              <MoreHorizontal className="h-4 w-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem onClick={handleResetPassword}>
              <Key className="mr-2 h-4 w-4" /> Reset Password
            </DropdownMenuItem>
            <DropdownMenuItem onClick={handleToggleStatus}>
              <PowerOff className="mr-2 h-4 w-4" /> {user.is_active ? "Deactivate" : "Activate"}
            </DropdownMenuItem>
            <DropdownMenuItem className="text-destructive focus:text-destructive" onClick={handleDelete}>
              <Trash className="mr-2 h-4 w-4" /> Delete User
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      );
    },
  },
];

"use client";

import { useForm, type Resolver } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { toast } from "sonner";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { createStudent } from "@/features/admin/user-actions";
import { useRouter } from "next/navigation";
import { AppModal } from "@/components/overlays/app-modal";

const schema = z.object({
  full_name: z.string().min(2, "Name is required"),
  email: z.string().email("Invalid email address"),
  roll_number: z.string().min(1, "Roll Number is required"),
  department_id: z.string().min(1, "Department is required"),
  semester_id: z.string().min(1, "Semester is required"),
  section_id: z.string().min(1, "Section is required"),
  batch_year: z.coerce.number().min(2000, "Invalid year"),
});

type FormData = z.infer<typeof schema>;

interface StudentFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  departments: Array<{ id: string; name: string }>;
  semesters: Array<{ id: string; semester_number: number }>;
  sections: Array<{ id: string; name: string }>;
}

export function StudentForm({ open, onOpenChange, departments, semesters, sections }: StudentFormProps) {
  const router = useRouter();

  const form = useForm<FormData>({
    resolver: zodResolver(schema) as unknown as Resolver<FormData>,
    defaultValues: {
      full_name: "", email: "", roll_number: "", department_id: "", semester_id: "", section_id: "", batch_year: new Date().getFullYear(),
    },
  });

  async function onSubmit(values: FormData) {
    const result = await createStudent(values);
    if (result.error) toast.error(result.error);
    else {
      toast.success("Student created successfully. Default password is 'Welcome@2024'");
      onOpenChange(false);
      form.reset();
      router.refresh();
    }
  }

  return (
    <AppModal title="Add Student" open={open} onOpenChange={(val) => { onOpenChange(val); if (!val) form.reset(); }}>
      <Form {...form}>
        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <FormField control={form.control} name="full_name" render={({ field }) => (
              <FormItem><FormLabel>Full Name</FormLabel><FormControl><Input {...field} /></FormControl><FormMessage /></FormItem>
            )} />
