      <AdminTimetableClient 
        sections={formattedSections} 
        faculty={formattedFaculty} 
        subjects={subjects || []} 
      />
    </div>
  );
}

"use client";

import { useState } from "react";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { gradeSubmission, getSubmissionSignedUrl } from "@/features/assignments/actions";
import { ExternalLink, CheckCircle2, AlertCircle, Loader2 } from "lucide-react";
import { format, parseISO } from "date-fns";

export function AssignmentGradingClient({ 
  assignment, 
  gradingData 
}: { 
  assignment: any; 
  gradingData: any[];
}) {
  const [data, setData] = useState(gradingData);
  const [selectedSub, setSelectedSub] = useState<any>(null);
  const [isGradeOpen, setIsGradeOpen] = useState(false);
  const [saving, setSaving] = useState(false);

  // Grade Form
  const [marks, setMarks] = useState("");
  const [feedback, setFeedback] = useState("");

  const handleOpenGrade = (sub: any) => {
    setSelectedSub(sub);
    setMarks(sub.marks_obtained?.toString() || "");
    setFeedback(sub.feedback || "");
    setIsGradeOpen(true);
  };

  const handleSaveGrade = async () => {
    if (!selectedSub?.submission_id) return;

    const numMarks = parseInt(marks, 10);
    if (isNaN(numMarks) || numMarks < 0 || numMarks > assignment.max_marks) {
      toast.error(`Marks must be between 0 and ${assignment.max_marks}`);
      return;
    }

    setSaving(true);
    const result = await gradeSubmission(selectedSub.submission_id, numMarks, feedback);
    if (result.error) {
      toast.error(result.error);
    } else {
      toast.success("Grade saved!");
      setData(data.map(d => 
        d.submission_id === selectedSub.submission_id 
          ? { ...d, marks_obtained: numMarks, feedback } 
          : d
      ));
      setIsGradeOpen(false);
    }
    setSaving(false);
  };

  const handleViewFile = async (filePath: string) => {
    const toastId = toast.loading("Generating secure link...");
    const result = await getSubmissionSignedUrl(filePath);
    if (result.error) {
      toast.error(result.error, { id: toastId });
    } else {
      toast.dismiss(toastId);
      window.open(result.url, "_blank");
    }
  };

  return (
    <div className="rounded-md border bg-card">
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead>Student</TableHead>
            <TableHead>Status</TableHead>
            <TableHead>Submitted At</TableHead>
            <TableHead>Marks</TableHead>
            <TableHead className="text-right">Actions</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {data.map((student) => {
            const isSubmitted = !!student.submission_id;
            const isGraded = student.marks_obtained !== null;
            let statusBadge = <Badge variant="secondary">Not Submitted</Badge>;

            if (isSubmitted) {
              const subTime = new Date(student.submitted_at);
              const deadline = new Date(assignment.deadline);
              if (subTime > deadline) {
                statusBadge = <Badge variant="destructive" className="flex w-fit items-center"><AlertCircle className="h-3 w-3 mr-1" /> Late</Badge>;
              } else {
                statusBadge = <Badge variant="default" className="flex w-fit items-center bg-green-600 hover:bg-green-700"><CheckCircle2 className="h-3 w-3 mr-1" /> On Time</Badge>;
              }
            }

            return (
              <TableRow key={student.student_id}>
                <TableCell>
                  <div className="font-medium">{student.student_name}</div>
                  <div className="text-xs text-muted-foreground">{student.enrollment_number}</div>
                </TableCell>
                <TableCell>{statusBadge}</TableCell>
                <TableCell>
                  {student.submitted_at 
                    ? format(parseISO(student.submitted_at), "MMM d, h:mm a") 
                    : "-"}
                </TableCell>
                <TableCell>
                  {isGraded ? (
                    <span className="font-bold">{student.marks_obtained} <span className="text-muted-foreground text-xs font-normal">/ {assignment.max_marks}</span></span>
                  ) : "-"}
                </TableCell>
                <TableCell className="text-right">
                  <div className="flex justify-end gap-2">
                    {student.file_url && (
                      <Button variant="outline" size="sm" onClick={() => handleViewFile(student.file_url)}>
                        <ExternalLink className="h-4 w-4 mr-2" /> View File
                      </Button>
                    )}
                    {isSubmitted && (
                      <Button size="sm" variant={isGraded ? "secondary" : "default"} onClick={() => handleOpenGrade(student)}>
                        {isGraded ? "Edit Grade" : "Grade"}
                      </Button>
                    )}
                  </div>
                </TableCell>
              </TableRow>
            );
          })}
          {data.length === 0 && (
            <TableRow>
              <TableCell colSpan={5} className="h-24 text-center">
                No students found in assigned sections.
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>

      <Dialog open={isGradeOpen} onOpenChange={setIsGradeOpen}>
        <DialogContent className="sm:max-w-[425px]">
          <DialogHeader>
            <DialogTitle>Grade Submission</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 pt-4">
            <div className="flex flex-col gap-1">
              <span className="text-sm font-semibold">{selectedSub?.student_name}</span>
              <span className="text-xs text-muted-foreground">{selectedSub?.enrollment_number}</span>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">Marks Obtained (Max: {assignment.max_marks})</label>
              <Input 
                type="number" 
                min="0" 
                max={assignment.max_marks} 
                value={marks} 
                onChange={(e) => setMarks(e.target.value)} 
              />
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium">Feedback (Optional)</label>
              <textarea 
                className="flex min-h-[100px] w-full rounded-md border border-input bg-background px-3 py-2 text-sm" 
                value={feedback} 
                onChange={(e) => setFeedback(e.target.value)}
                placeholder="Great job on..."
              />
            </div>
            <Button onClick={handleSaveGrade} className="w-full" disabled={saving}>
              {saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {saving ? "Saving..." : "Save Grade"}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { getUserProfile } from "@/features/auth/user";
import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { AssignmentGradingClient } from "./client";
import { ChevronLeft } from "lucide-react";
import Link from "next/link";
import { Button } from "@/components/ui/button";

export default async function GradingPage({ params }: { params: Promise<{ id: string }> }) {
  const resolvedParams = await params;
  const profile = await getUserProfile();
  if (!profile || profile.role !== "faculty") {
    redirect("/login");
  }

  const supabase = await createClient();

  // Fetch assignment details
  const { data: assignment, error: assignErr } = await (supabase as any)
    .from("assignments")
    .select(`
      id,
      title,
      max_marks,
      deadline,
      subject_id,
      subjects (
        name,
        code
      )
    `)
    .eq("id", resolvedParams.id)
    .single();

  if (assignErr || !assignment) {
    return <div className="p-8">Assignment not found</div>;
  }

  // Fetch all students enrolled in this subject's section
  // 1. We need to find the sections this faculty teaches for this subject
  const { data: facAssignments } = await (supabase as any)
    .from("faculty_assignments")
    .select("section_id")
    .eq("faculty_id", profile.id)
    .eq("subject_id", assignment.subject_id);

  const sectionIds = facAssignments?.map((f: any) => f.section_id) || [];

  // 2. Find students in these sections
  const { data: students } = await (supabase as any)
    .from("students")
    .select(`
      profile_id,
      enrollment_number,
      profiles (
        full_name
      )
    `)
    .in("section_id", sectionIds);

  // 3. Fetch submissions for this assignment
  const { data: submissions } = await (supabase as any)
    .from("assignment_submissions")
    .select(`
      id,
      student_id,
      file_url,
      submitted_at,
      marks_obtained,
      feedback
    `)
    .eq("assignment_id", resolvedParams.id);

  // 4. Map them together
  const gradingData = (students || []).map((student: any) => {
    const sub = submissions?.find((s: any) => s.student_id === student.profile_id);
    return {
      student_id: student.profile_id,
      student_name: student.profiles?.full_name || "Unknown",
      enrollment_number: student.enrollment_number,
      submission_id: sub?.id || null,
      file_url: sub?.file_url || null,
      submitted_at: sub?.submitted_at || null,
      marks_obtained: sub?.marks_obtained ?? null,
      feedback: sub?.feedback || ""
    };
  });

  return (
    <div className="flex-1 space-y-6 p-4 md:p-8 pt-6 pb-24">
      <div className="flex items-center gap-4">
        <Button variant="outline" size="icon" asChild>
          <Link href="/faculty/assignments">
            <ChevronLeft className="h-4 w-4" />
          </Link>
        </Button>
        <div className="flex flex-col gap-1">
          <h1 className="text-2xl font-bold tracking-tight">Grade Submissions</h1>
          <p className="text-muted-foreground text-sm">
            {assignment.title} ({assignment.subjects?.code}) - Max Marks: {assignment.max_marks}
          </p>
        </div>
      </div>

      <AssignmentGradingClient 
        assignment={assignment} 
        gradingData={gradingData} 
      />
    </div>
  );
}

"use client";

import { useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { createAssignment } from "@/features/assignments/actions";
import { toast } from "sonner";
import { Loader2, Plus, FileText, CalendarClock, Users, ArrowRight } from "lucide-react";
import { format, parseISO } from "date-fns";
import Link from "next/link";
import { Badge } from "@/components/ui/badge";

export function FacultyAssignmentsClient({ 
  facultyId, 
  subjects, 
  initialAssignments 
}: { 
  facultyId: string; 
  subjects: any[]; 
  initialAssignments: any[];
}) {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [uploading, setUploading] = useState(false);

  // Form State
  const [subjectId, setSubjectId] = useState("");
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [deadline, setDeadline] = useState("");
  const [maxMarks, setMaxMarks] = useState("100");
  const [file, setFile] = useState<File | null>(null);

  const handleUpload = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!subjectId || !title || !deadline || !maxMarks) {
      toast.error("Please fill all required fields");
      return;
    }

    setUploading(true);
    const formData = new FormData();
    formData.append("faculty_id", facultyId);
    formData.append("subject_id", subjectId);
    formData.append("title", title);
    formData.append("description", description);

    // Ensure deadline is valid ISO with timezone for Postgres
    const localDate = new Date(deadline);
    formData.append("deadline", localDate.toISOString());

    formData.append("max_marks", maxMarks);
    if (file) formData.append("file", file);

    const result = await createAssignment(formData);

    if (result.error) {
      toast.error(result.error);
    } else {
      toast.success("Assignment created successfully!");
      setIsAddOpen(false);
      window.location.reload(); 
    }
    setUploading(false);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div className="flex gap-4">
          <Card className="px-4 py-2 flex flex-col justify-center bg-primary/5 border-primary/20">
            <span className="text-xs text-muted-foreground font-semibold uppercase">Total Created</span>
            <span className="text-2xl font-bold">{initialAssignments.length}</span>
          </Card>
        </div>
        <Dialog open={isAddOpen} onOpenChange={setIsAddOpen}>
          <DialogTrigger asChild>
            <Button><Plus className="h-4 w-4 mr-2" /> Create Assignment</Button>
          </DialogTrigger>
          <DialogContent className="sm:max-w-[500px]">
            <DialogHeader>
              <DialogTitle>Create New Assignment</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleUpload} className="space-y-4 pt-4">
              <div className="space-y-2">
                <Label>Subject *</Label>
                <select required value={subjectId} onChange={e => setSubjectId(e.target.value)} className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm">
                  <option value="">Select subject...</option>
                  {subjects.map(s => (
                    <option key={s.id} value={s.id}>{s.code} - {s.name}</option>
                  ))}
                </select>
              </div>
              <div className="space-y-2">
                <Label>Title *</Label>
                <Input required value={title} onChange={e => setTitle(e.target.value)} placeholder="e.g. Midterm Case Study" />
              </div>
              <div className="space-y-2">
                <Label>Instructions</Label>
                <textarea 
                  className="flex min-h-[80px] w-full rounded-md border border-input bg-background px-3 py-2 text-sm" 
                  value={description} 
                  onChange={e => setDescription(e.target.value)} 
                  placeholder="Details and guidelines..." 
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>Deadline *</Label>
                  <Input required type="datetime-local" value={deadline} onChange={e => setDeadline(e.target.value)} />
                </div>
                <div className="space-y-2">
                  <Label>Maximum Marks *</Label>
                  <Input required type="number" min="1" value={maxMarks} onChange={e => setMaxMarks(e.target.value)} />
                </div>
              </div>
              <div className="space-y-2">
                <Label>Reference Material (Optional)</Label>
                <Input type="file" onChange={e => setFile(e.target.files?.[0] || null)} />
                <p className="text-xs text-muted-foreground">Attach a PDF, DOCX, or ZIP containing instructions or datasets (Max 50MB).</p>
              </div>

              <Button type="submit" className="w-full mt-4" disabled={uploading}>
                {uploading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                {uploading ? "Publishing..." : "Publish Assignment"}
              </Button>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      {initialAssignments.length === 0 ? (
        <Card className="flex flex-col items-center justify-center p-12 text-center bg-muted/30 border-dashed">
          <FileText className="h-12 w-12 text-muted-foreground/30 mb-4" />
          <h3 className="text-lg font-semibold text-muted-foreground">No assignments created</h3>
          <p className="text-muted-foreground text-sm max-w-sm mt-1">Create your first assignment to start evaluating students.</p>
        </Card>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {initialAssignments.map(a => {
            const isOverdue = new Date() > new Date(a.deadline);

            return (
