"use client";

import { useState, useEffect } from "react";
import { format } from "date-fns";
import { toast } from "sonner";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

import { Badge } from "@/components/ui/badge";
import { getStudentsForSection, getAttendanceRecord, saveAttendanceRecord } from "@/features/attendance/faculty-actions";
import { Loader2, Users, Save, CheckCircle2, XCircle, Clock } from "lucide-react";
import { Label } from "@/components/ui/label";

type AssignedSubject = {
  subject_id: string;
  subject_name: string;
  subject_code: string;
  section_id: string;
  section_name: string;
  semester_number: number;
  program_name: string;
  department_name: string;
};

type Student = {
  profile_id: string;
  roll_number: string;
  profiles: {
    full_name: string;
    email: string;
    avatar_url: string | null;
  };
};

export function AttendanceClient({ initialSubjects }: { initialSubjects: AssignedSubject[] }) {
  const [selectedClassStr, setSelectedClassStr] = useState<string>("");
  const [date, setDate] = useState<string>(format(new Date(), "yyyy-MM-dd"));

  const [students, setStudents] = useState<Student[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  // Mapping of student_id -> status
  const [attendanceState, setAttendanceState] = useState<Record<string, "present" | "absent" | "late">>({});

  const loadAttendance = async () => {
    if (!selectedClassStr || !date) return;

    setLoading(true);
    const [subjectId, sectionId] = selectedClassStr.split("|");

    // 1. Fetch Students
    const { data: stdData, error: stdErr } = await getStudentsForSection(sectionId);
    if (stdErr) {
      toast.error(stdErr);
      setLoading(false);
      return;
    }

    const fetchedStudents = stdData || [];
    setStudents(fetchedStudents);

    // 2. Fetch existing records
    const { data: attData, error: attErr } = await getAttendanceRecord(sectionId, subjectId, date);

    const newState: Record<string, "present" | "absent" | "late"> = {};

    if (attData && attData.attendance_records) {
      // Load existing state
      (attData.attendance_records as any[]).forEach((r: any) => {
        newState[r.student_id] = r.status;
      });
    } else {
      // Default to Present
      fetchedStudents.forEach((s: Student) => {
        newState[s.profile_id] = "present";
      });
    }

    setAttendanceState(newState);
    setLoading(false);
  };

  useEffect(() => {
    loadAttendance();
  }, [selectedClassStr, date]);

  const handleStatusChange = (studentId: string, status: "present" | "absent" | "late") => {
    setAttendanceState((prev) => ({ ...prev, [studentId]: status }));
  };

  const handleBulkMark = (status: "present" | "absent" | "late") => {
    const newState = { ...attendanceState };
    students.forEach((s: Student) => {
      newState[s.profile_id] = status;
    });
    setAttendanceState(newState);
  };

  const handleSave = async () => {
    if (!selectedClassStr || !date) return;
    setSaving(true);

    const [subjectId, sectionId] = selectedClassStr.split("|");
    const recordsToSave = Object.keys(attendanceState).map((student_id) => ({
      student_id,
      status: attendanceState[student_id],
    }));

    const result = await saveAttendanceRecord(sectionId, subjectId, date, recordsToSave);

    if (result.error) {
      toast.error(result.error);
    } else {
      toast.success("Attendance saved successfully!");
    }

    setSaving(false);
  };

  return (
    <div className="space-y-6">
      {/* Controls */}
      <Card>
        <CardContent className="pt-6">
          <div className="flex flex-col md:flex-row gap-4">
            <div className="flex-1 space-y-2">
              <Label>Select Class (Subject & Section)</Label>
              <select value={selectedClassStr} onChange={(e) => setSelectedClassStr(e.target.value)} className="flex h-9 w-full items-center justify-between whitespace-nowrap rounded-md border border-input bg-transparent px-3 py-2 text-sm shadow-sm ring-offset-background placeholder:text-muted-foreground focus:outline-none focus:ring-1 focus:ring-ring disabled:cursor-not-allowed disabled:opacity-50 [&>span]:line-clamp-1">
                <option value="">Choose a class...</option>
                {initialSubjects.map((s, i) => (
                  <option key={i} value={`${s.subject_id}|${s.section_id}`}>
                    {s.subject_code} - {s.subject_name} ({s.section_name})
                  </option>
                ))}
              </select>
            </div>
            <div className="w-full md:w-[200px] space-y-2">
              <Label>Date</Label>
              <Input type="date" value={date} onChange={(e) => setDate(e.target.value)} max={format(new Date(), "yyyy-MM-dd")} />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Grid */}
      {loading ? (
        <div className="flex items-center justify-center p-12">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
        </div>
      ) : selectedClassStr && students.length > 0 ? (
        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-4">
            <CardTitle className="text-lg flex items-center gap-2">
              <Users className="h-5 w-5" /> Enrolled Students ({students.length})
            </CardTitle>
            <div className="flex items-center gap-2">
              <Button size="sm" variant="outline" onClick={() => handleBulkMark("present")}>Mark All Present</Button>
              <Button size="sm" onClick={handleSave} disabled={saving}>
                {saving ? <Loader2 className="h-4 w-4 mr-2 animate-spin" /> : <Save className="h-4 w-4 mr-2" />}
                Save Attendance
              </Button>
            </div>
          </CardHeader>
          <CardContent>
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
              {students.map((student) => {
                const status = attendanceState[student.profile_id] || "present";
                return (
                  <div key={student.profile_id} className={`flex flex-col gap-3 rounded-lg border p-3 transition-colors ${status === "present" ? "border-green-500/30 bg-green-500/5" : status === "absent" ? "border-red-500/30 bg-red-500/5" : "border-amber-500/30 bg-amber-500/5"}`}>
                    <div>
                      <div className="font-semibold text-sm truncate" title={student.profiles.full_name}>{student.profiles.full_name}</div>
                      <div className="text-xs text-muted-foreground">{student.roll_number}</div>
                    </div>
                    <div className="flex items-center justify-between gap-1 bg-background rounded p-1 border">
                      <button
                        onClick={() => handleStatusChange(student.profile_id, "present")}
                        className={`flex-1 flex justify-center py-1.5 rounded transition-all ${status === "present" ? "bg-green-500 text-white shadow-sm" : "text-muted-foreground hover:bg-muted"}`}
                        title="Present"
                      >
                        <CheckCircle2 className="h-4 w-4" />
                      </button>
                      <button
                        onClick={() => handleStatusChange(student.profile_id, "late")}
                        className={`flex-1 flex justify-center py-1.5 rounded transition-all ${status === "late" ? "bg-amber-500 text-white shadow-sm" : "text-muted-foreground hover:bg-muted"}`}
                        title="Late"
                      >
                        <Clock className="h-4 w-4" />
                      </button>
                      <button
                        onClick={() => handleStatusChange(student.profile_id, "absent")}
                        className={`flex-1 flex justify-center py-1.5 rounded transition-all ${status === "absent" ? "bg-red-500 text-white shadow-sm" : "text-muted-foreground hover:bg-muted"}`}
                        title="Absent"
                      >
                        <XCircle className="h-4 w-4" />
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          </CardContent>
        </Card>
      ) : selectedClassStr ? (
        <Card className="flex flex-col items-center justify-center p-12 text-center">
          <Users className="h-12 w-12 text-muted-foreground/50 mb-4" />
          <h3 className="text-lg font-semibold">No students found</h3>
          <p className="text-muted-foreground text-sm max-w-sm mt-1">There are no students enrolled in this section. Please contact administration.</p>
        </Card>
      ) : (
        <Card className="flex flex-col items-center justify-center p-12 text-center bg-muted/30 border-dashed">
          <CheckCircle2 className="h-12 w-12 text-muted-foreground/30 mb-4" />
          <h3 className="text-lg font-semibold text-muted-foreground">Ready to take attendance</h3>
          <p className="text-muted-foreground text-sm max-w-sm mt-1">Select a class from the dropdown above to begin marking attendance.</p>
        </Card>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { createNote, deleteNote } from "@/features/notes/actions";
import { toast } from "sonner";
import { Loader2, Plus, File, Image as ImageIcon, Link as LinkIcon, Trash2, FileText, PlayCircle, FileArchive, Download } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { format, parseISO } from "date-fns";

export function FacultyNotesClient({ 
  facultyId, 
  subjects, 
  initialNotes 
}: { 
  facultyId: string; 
  subjects: any[]; 
  initialNotes: any[];
}) {
  const [notes, setNotes] = useState(initialNotes);
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [uploading, setUploading] = useState(false);

  // Form State
  const [subjectId, setSubjectId] = useState("");
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [unit, setUnit] = useState("");
  const [resourceType, setResourceType] = useState("pdf");
  const [url, setUrl] = useState("");
  const [file, setFile] = useState<File | null>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setFile(e.target.files[0]);
    }
  };

  const handleUpload = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!subjectId || !title) {
      toast.error("Subject and Title are required");
      return;
    }

    const requiresFile = ["pdf", "ppt", "docx", "zip", "image"].includes(resourceType);
    if (requiresFile && !file) {
      toast.error("Please select a file to upload");
      return;
    }
    if (!requiresFile && !url) {
      toast.error("Please provide a valid URL");
      return;
    }

    setUploading(true);
    const formData = new FormData();
    formData.append("faculty_id", facultyId);
    formData.append("subject_id", subjectId);
    formData.append("title", title);
    formData.append("description", description);
    formData.append("unit", unit);
    formData.append("resource_type", resourceType);
    if (url) formData.append("url", url);
    if (file) formData.append("file", file);

    const result = await createNote(formData);

    if (result.error) {
      toast.error(result.error);
    } else {
      toast.success("Study material uploaded successfully!");
      setIsAddOpen(false);
      // Let server component handle fresh data on reload, but we can just reload for simplicity
      window.location.reload(); 
    }
    setUploading(false);
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this material?")) return;
    const result = await deleteNote(id);
    if (result.error) {
      toast.error(result.error);
    } else {
      toast.success("Material deleted");
      setNotes(notes.filter(n => n.id !== id));
    }
  };

  const getIcon = (type: string) => {
    switch (type) {
      case "pdf": return <FileText className="h-5 w-5 text-red-500" />;
      case "ppt": return <File className="h-5 w-5 text-orange-500" />;
      case "docx": return <FileText className="h-5 w-5 text-blue-500" />;
      case "zip": return <FileArchive className="h-5 w-5 text-yellow-500" />;
      case "image": return <ImageIcon className="h-5 w-5 text-green-500" />;
      case "youtube": return <PlayCircle className="h-5 w-5 text-red-600" />;
      default: return <LinkIcon className="h-5 w-5 text-blue-400" />;
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-xl font-semibold">My Uploads</h2>
        <Dialog open={isAddOpen} onOpenChange={setIsAddOpen}>
          <DialogTrigger asChild>
            <Button><Plus className="h-4 w-4 mr-2" /> Upload Material</Button>
          </DialogTrigger>
          <DialogContent className="sm:max-w-[500px]">
            <DialogHeader>
              <DialogTitle>Upload Study Material</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleUpload} className="space-y-4 pt-4">
              <div className="space-y-2">
                <Label>Subject</Label>
                <select required value={subjectId} onChange={e => setSubjectId(e.target.value)} className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm">
                  <option value="">Select subject...</option>
                  {subjects.map(s => (
                    <option key={s.id} value={s.id}>{s.code} - {s.name}</option>
                  ))}
                </select>
              </div>
              <div className="space-y-2">
                <Label>Title</Label>
                <Input required value={title} onChange={e => setTitle(e.target.value)} placeholder="e.g. Chapter 1 Notes" />
              </div>
              <div className="space-y-2">
                <Label>Description (Optional)</Label>
                <Input value={description} onChange={e => setDescription(e.target.value)} placeholder="Brief description of the material" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>Unit / Module</Label>
                  <Input value={unit} onChange={e => setUnit(e.target.value)} placeholder="e.g. Unit 1" />
                </div>
                <div className="space-y-2">
                  <Label>Resource Type</Label>
                  <select required value={resourceType} onChange={e => setResourceType(e.target.value)} className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm">
                    <option value="pdf">PDF Document</option>
                    <option value="ppt">PowerPoint (PPT)</option>
                    <option value="docx">Word Document</option>
                    <option value="zip">ZIP Archive</option>
                    <option value="image">Image</option>
                    <option value="youtube">YouTube Video</option>
                    <option value="link">External Link</option>
                  </select>
                </div>
              </div>

              {["link", "youtube"].includes(resourceType) ? (
                <div className="space-y-2">
                  <Label>URL</Label>
                  <Input required type="url" value={url} onChange={e => setUrl(e.target.value)} placeholder="https://" />
                </div>
              ) : (
                <div className="space-y-2">
                  <Label>File Upload (Max 50MB)</Label>
                  <Input required type="file" onChange={handleFileChange} />
                </div>
              )}

              <Button type="submit" className="w-full mt-4" disabled={uploading}>
                {uploading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                {uploading ? "Uploading..." : "Upload Material"}
              </Button>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      {notes.length === 0 ? (
        <Card className="flex flex-col items-center justify-center p-12 text-center bg-muted/30 border-dashed">
          <File className="h-12 w-12 text-muted-foreground/30 mb-4" />
          <h3 className="text-lg font-semibold text-muted-foreground">No materials uploaded yet</h3>
          <p className="text-muted-foreground text-sm max-w-sm mt-1">Upload your first study material to share with students.</p>
        </Card>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {notes.map(note => (
            <Card key={note.id} className="flex flex-col h-full hover:shadow-md transition-shadow">
              <CardContent className="p-5 flex flex-col flex-1">
                <div className="flex justify-between items-start mb-3">
                  <div className="flex items-center gap-2 bg-muted px-2 py-1 rounded-md text-xs font-semibold uppercase">
                    {getIcon(note.resource_type)}
                    <span>{note.resource_type}</span>
                  </div>
                  {note.unit && <Badge variant="outline">{note.unit}</Badge>}
                </div>

                <h3 className="font-bold text-lg leading-tight mb-1 line-clamp-2" title={note.title}>{note.title}</h3>
                <div className="text-xs font-medium text-primary mb-2">{note.subject_code} - {note.subject_name}</div>

                {note.description && (
                  <p className="text-sm text-muted-foreground line-clamp-2 mb-4 flex-1">
                    {note.description}
                  </p>
                )}

                <div className="mt-auto pt-4 flex items-center justify-between border-t border-border/50">
                  <span className="text-xs text-muted-foreground">{format(parseISO(note.created_at), "MMM d, yyyy")}</span>
                  <div className="flex gap-2">
                    <a href={note.url} target="_blank" rel="noreferrer" className="inline-flex items-center justify-center rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 hover:bg-accent hover:text-accent-foreground h-8 w-8">
                      <Download className="h-4 w-4" />
                    </a>
                    <button onClick={() => handleDelete(note.id)} className="inline-flex items-center justify-center rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring hover:bg-destructive/10 text-destructive h-8 w-8">
                      <Trash2 className="h-4 w-4" />
                    </button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { createQuiz } from "@/features/quizzes/actions";
import { toast } from "sonner";
import { Loader2, Plus, BrainCircuit, CalendarClock, Users, Trash2, SwitchCamera, Clock, CheckCircle2 } from "lucide-react";
import { format, parseISO } from "date-fns";
import { Badge } from "@/components/ui/badge";

export function FacultyQuizzesClient({ 
  facultyId, 
  subjects, 
  initialQuizzes 
}: { 
  facultyId: string; 
  subjects: any[]; 
  initialQuizzes: any[];
}) {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [uploading, setUploading] = useState(false);

  // Form State
  const [subjectId, setSubjectId] = useState("");
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [timeLimit, setTimeLimit] = useState("30");
  const [startTime, setStartTime] = useState("");
  const [endTime, setEndTime] = useState("");
  const [isPublished, setIsPublished] = useState(false);

  // Questions State
  const [questions, setQuestions] = useState<any[]>([]);

  const addQuestion = (type: 'MCQ' | 'TrueFalse' | 'ShortAnswer') => {
    setQuestions([...questions, {
      id: Math.random().toString(),
      question_text: "",
      question_type: type,
      options: type === 'MCQ' ? ["", "", "", ""] : (type === 'TrueFalse' ? ["True", "False"] : []),
      correct_answer: "",
      points: 1
    }]);
  };

  const updateQuestion = (index: number, field: string, value: any) => {
    const newQs = [...questions];
    newQs[index][field] = value;
    setQuestions(newQs);
  };

  const updateOption = (qIndex: number, optIndex: number, value: string) => {
    const newQs = [...questions];
    newQs[qIndex].options[optIndex] = value;
    setQuestions(newQs);
  };

  const removeQuestion = (index: number) => {
    const newQs = [...questions];
    newQs.splice(index, 1);
    setQuestions(newQs);
  };

  const handleUpload = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!subjectId || !title || !startTime || !endTime) {
      toast.error("Please fill all required quiz settings");
      return;
    }
    if (questions.length === 0) {
      toast.error("Please add at least one question");
      return;
    }

    // Validate questions
    for (const [i, q] of questions.entries()) {
      if (!q.question_text) return toast.error(`Question ${i+1} is missing text`);
      if (!q.correct_answer) return toast.error(`Question ${i+1} is missing a correct answer`);
      if (q.question_type === 'MCQ' && q.options.some((o: string) => !o)) {
        return toast.error(`Question ${i+1} is missing MCQ options`);
      }
    }

    setUploading(true);
    const formData = new FormData();
    formData.append("faculty_id", facultyId);
    formData.append("subject_id", subjectId);
    formData.append("title", title);
    formData.append("description", description);
    formData.append("time_limit_minutes", timeLimit);

    // Convert to ISO with local timezone applied by the browser date input
    formData.append("start_time", new Date(startTime).toISOString());
    formData.append("end_time", new Date(endTime).toISOString());
    formData.append("is_published", String(isPublished));

    const result = await createQuiz(formData, questions);

    if (result.error) {
      toast.error(result.error);
    } else {
      toast.success("Quiz created successfully!");
      setIsAddOpen(false);
      window.location.reload(); 
    }
    setUploading(false);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div className="flex gap-4">
          <Card className="px-4 py-2 flex flex-col justify-center bg-primary/5 border-primary/20">
            <span className="text-xs text-muted-foreground font-semibold uppercase">Total Quizzes</span>
            <span className="text-2xl font-bold">{initialQuizzes.length}</span>
          </Card>
        </div>
        <Dialog open={isAddOpen} onOpenChange={setIsAddOpen}>
          <DialogTrigger asChild>
            <Button><Plus className="h-4 w-4 mr-2" /> Create Quiz</Button>
          </DialogTrigger>
          <DialogContent className="sm:max-w-[700px] max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>Create New Quiz</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleUpload} className="space-y-6 pt-4">
              <div className="space-y-4 border-b pb-6">
                <h3 className="font-semibold">Quiz Settings</h3>
                <div className="space-y-2">
                  <Label>Subject *</Label>
                  <select required value={subjectId} onChange={e => setSubjectId(e.target.value)} className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm">
                    <option value="">Select subject...</option>
                    {subjects.map(s => (
                      <option key={s.id} value={s.id}>{s.code} - {s.name}</option>
                    ))}
                  </select>
                </div>
                <div className="space-y-2">
                  <Label>Quiz Title *</Label>
                  <Input required value={title} onChange={e => setTitle(e.target.value)} placeholder="e.g. Unit 1 Pop Quiz" />
                </div>
                <div className="space-y-2">
                  <Label>Description</Label>
                  <textarea 
                    className="flex min-h-[60px] w-full rounded-md border border-input bg-background px-3 py-2 text-sm" 
                    value={description} 
                    onChange={e => setDescription(e.target.value)} 
                    placeholder="Brief instructions..." 
                  />
                </div>

                <div className="grid grid-cols-3 gap-4">
                  <div className="space-y-2">
                    <Label>Time Limit (mins) *</Label>
                    <Input required type="number" min="1" value={timeLimit} onChange={e => setTimeLimit(e.target.value)} />
                  </div>
                  <div className="space-y-2">
                    <Label>Start Window *</Label>
                    <Input required type="datetime-local" value={startTime} onChange={e => setStartTime(e.target.value)} />
                  </div>
                  <div className="space-y-2">
                    <Label>End Window *</Label>
                    <Input required type="datetime-local" value={endTime} onChange={e => setEndTime(e.target.value)} />
                  </div>
                </div>

                <div className="flex items-center space-x-2">
                  <input type="checkbox" id="published" checked={isPublished} onChange={e => setIsPublished(e.target.checked)} className="rounded border-input" />
                  <Label htmlFor="published">Publish Immediately</Label>
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex justify-between items-center">
                  <h3 className="font-semibold">Questions ({questions.length})</h3>
                  <div className="flex gap-2">
                    <Button type="button" variant="outline" size="sm" onClick={() => addQuestion('MCQ')}>+ MCQ</Button>
                    <Button type="button" variant="outline" size="sm" onClick={() => addQuestion('TrueFalse')}>+ T/F</Button>
                    <Button type="button" variant="outline" size="sm" onClick={() => addQuestion('ShortAnswer')}>+ Short Answer</Button>
                  </div>
                </div>

                <div className="space-y-4">
                  {questions.map((q, i) => (
                    <Card key={q.id} className="relative">
                      <Button type="button" variant="ghost" size="icon" className="absolute top-2 right-2 text-destructive" onClick={() => removeQuestion(i)}>
                        <Trash2 className="h-4 w-4" />
                      </Button>
                      <CardContent className="pt-6 space-y-4">
                        <div className="flex gap-4">
                          <span className="font-bold text-muted-foreground w-6">{i+1}.</span>
                          <div className="flex-1 space-y-2">
                            <Label>Question Text</Label>
                            <Input value={q.question_text} onChange={e => updateQuestion(i, 'question_text', e.target.value)} placeholder="Enter question..." />
                          </div>
                          <div className="space-y-2 w-24">
                            <Label>Points</Label>
                            <Input type="number" min="1" value={q.points} onChange={e => updateQuestion(i, 'points', parseInt(e.target.value))} />
                          </div>
                        </div>

                        <div className="pl-10 space-y-3">
                          {q.question_type === 'MCQ' && (
                            <div className="grid grid-cols-2 gap-2">
                              {q.options.map((opt: string, optIdx: number) => (
                                <Input key={optIdx} value={opt} onChange={e => updateOption(i, optIdx, e.target.value)} placeholder={`Option ${optIdx+1}`} />
                              ))}
                            </div>
                          )}

                          <div className="space-y-2">
                            <Label className="text-primary">Correct Answer *</Label>
                            {q.question_type === 'MCQ' ? (
                              <select required value={q.correct_answer} onChange={e => updateQuestion(i, 'correct_answer', e.target.value)} className="flex h-9 w-full rounded-md border border-input bg-background px-3 py-1 text-sm">
                                <option value="">Select correct option...</option>
                                {q.options.filter((o: string) => o).map((opt: string, optIdx: number) => (
                                  <option key={optIdx} value={opt}>{opt}</option>
                                ))}
                              </select>
                            ) : q.question_type === 'TrueFalse' ? (
                              <select required value={q.correct_answer} onChange={e => updateQuestion(i, 'correct_answer', e.target.value)} className="flex h-9 w-full rounded-md border border-input bg-background px-3 py-1 text-sm">
                                <option value="">Select true/false...</option>
                                <option value="True">True</option>
                                <option value="False">False</option>
                              </select>
                            ) : (
                              <Input value={q.correct_answer} onChange={e => updateQuestion(i, 'correct_answer', e.target.value)} placeholder="Exact answer (case-insensitive)" />
                            )}
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </div>

              <Button type="submit" className="w-full mt-4" disabled={uploading}>
                {uploading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                {uploading ? "Saving Quiz..." : "Save Quiz"}
              </Button>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      {initialQuizzes.length === 0 ? (
        <Card className="flex flex-col items-center justify-center p-12 text-center bg-muted/30 border-dashed">
          <BrainCircuit className="h-12 w-12 text-muted-foreground/30 mb-4" />
          <h3 className="text-lg font-semibold text-muted-foreground">No quizzes created</h3>
          <p className="text-muted-foreground text-sm max-w-sm mt-1">Create interactive quizzes to test student knowledge.</p>
        </Card>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {initialQuizzes.map(q => {
            const now = new Date();
            const start = new Date(q.start_time);
            const end = new Date(q.end_time);
            let status = "Upcoming";
            if (now > end) status = "Closed";
            else if (now >= start && now <= end) status = "Active";

            return (
              <Card key={q.id} className="flex flex-col h-full hover:shadow-md transition-shadow">
                <CardContent className="p-5 flex flex-col flex-1">
                  <div className="flex justify-between items-start mb-3">
                    <Badge variant={status === "Active" ? "default" : status === "Closed" ? "secondary" : "outline"}>
                      {status}
                    </Badge>
                    <span className="text-xs font-bold text-muted-foreground bg-muted px-2 py-1 rounded-md flex items-center">
                      <Clock className="w-3 h-3 mr-1"/> {q.time_limit_minutes}m
                    </span>
                  </div>

                  <h3 className="font-bold text-lg leading-tight mb-1">{q.title}</h3>
                  <div className="text-xs font-medium text-primary mb-4">{q.subject_code} - {q.subject_name}</div>

                  <div className="mt-auto space-y-3">
                    <div className="flex items-center text-xs text-muted-foreground">
                      <CalendarClock className="h-3.5 w-3.5 mr-1.5" />
                      {format(parseISO(q.start_time), "MMM d, h:mm a")} - {format(parseISO(q.end_time), "h:mm a")}
                    </div>
                    <div className="flex justify-between items-center text-xs text-muted-foreground border-t border-border/50 pt-3">
                      <div className="flex items-center">
                        <Users className="h-3.5 w-3.5 mr-1.5" />
                        {q.attempts_count} Attempts
                      </div>
                      <div className="flex items-center">
                        <CheckCircle2 className="h-3.5 w-3.5 mr-1.5" />
                        {q.questions_count} Qs
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
}

