        kpis={kpisRes}
        trends={trendsRes.data}
        notices={noticesRes.data}
        facultyWorkload={facultyRes.facultyWorkload}
        sectionData={perfRes.sectionData}
        avgMarks={perfRes.avgMarks}
      />
    </div>
  );
}

import { getUserProfile } from "@/features/auth/user";
import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";

export default async function HodReportsPage() {
  const profile = await getUserProfile();
  if (!profile || profile.role !== "hod") {
    redirect("/login");
  }

  const supabase = await createClient();
  const { data: hodFaculty } = await (supabase as any)
    .from("faculty")
    .select("department_id")
    .eq("profile_id", profile.id)
    .single();

  if (!hodFaculty?.department_id) {
    return <div>No department assigned</div>;
  }

  const deptId = hodFaculty.department_id;

  // Fetch Faculty List with count of subjects they teach
  const { data: facultyData } = await (supabase as any)
    .from("faculty")
    .select(`
      id,
      users ( full_name, email ),
      designation,
      faculty_subjects ( count )
    `)
    .eq("department_id", deptId);

  // Fetch Students with low attendance (e.g. < 75%)
  // This is a naive implementation; ideally we calculate this in a materialized view
  // For the prototype, we will just fetch students in the department and their raw attendance
  const { data: attendanceData } = await (supabase as any)
    .from("attendance")
    .select(`
      status,
      student_id,
      subjects!inner(department_id),
      students!inner(users(full_name))
    `)
    .eq("subjects.department_id", deptId);

  const studentAtt: Record<string, { name: string, present: number, total: number }> = {};

  if (attendanceData) {
    attendanceData.forEach((a: any) => {
      if (!studentAtt[a.student_id]) {
        studentAtt[a.student_id] = { name: a.students.users.full_name, present: 0, total: 0 };
      }
      studentAtt[a.student_id].total += 1;
      if (a.status === "present") studentAtt[a.student_id].present += 1;
    });
  }

  const lowAttendanceStudents = Object.entries(studentAtt)
    .map(([id, stats]) => ({
      id,
      name: stats.name,
      percentage: Math.round((stats.present / stats.total) * 100)
    }))
    .filter(s => s.percentage < 75)
    .sort((a, b) => a.percentage - b.percentage);


  return (
    <div className="flex-1 space-y-6 p-8 pt-6">
      <div className="flex items-center justify-between space-y-2">
        <h2 className="text-3xl font-bold tracking-tight">Department Reports</h2>
      </div>

      <div className="grid gap-4 md:grid-cols-2">
        <Card>
          <CardHeader>
            <CardTitle>Faculty Workload</CardTitle>
            <CardDescription>Number of subjects assigned to faculty in your department.</CardDescription>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Faculty Name</TableHead>
                  <TableHead>Designation</TableHead>
                  <TableHead className="text-right">Subjects Assigned</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {facultyData?.map((faculty: any) => (
                  <TableRow key={faculty.id}>
                    <TableCell className="font-medium">{faculty.users?.full_name}</TableCell>
                    <TableCell>{faculty.designation}</TableCell>
                    <TableCell className="text-right">{faculty.faculty_subjects[0]?.count || 0}</TableCell>
                  </TableRow>
                ))}
                {(!facultyData || facultyData.length === 0) && (
                  <TableRow>
                    <TableCell colSpan={3} className="text-center h-24 text-muted-foreground">
                      No faculty found.
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Critical Attendance</CardTitle>
            <CardDescription>Students with attendance below 75%.</CardDescription>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Student Name</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="text-right">Attendance %</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {lowAttendanceStudents.map((student: any) => (
                  <TableRow key={student.id}>
                    <TableCell className="font-medium">{student.name}</TableCell>
                    <TableCell>
                      <Badge variant="destructive">Critical</Badge>
                    </TableCell>
                    <TableCell className="text-right font-bold text-destructive">
                      {student.percentage}%
                    </TableCell>
                  </TableRow>
                ))}
                {lowAttendanceStudents.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={3} className="text-center h-24 text-muted-foreground">
                      No students with critical attendance.
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { updateApplicationStatus } from "@/features/placement/actions";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { format } from "date-fns";
import { ExternalLink } from "lucide-react";

export function ApplicationsClient({ 
  drives, 
  initialApplications,
  selectedDriveId
}: { 
  drives: any[],
  initialApplications: any[],
  selectedDriveId?: string
}) {
  const router = useRouter();
  const [loadingId, setLoadingId] = useState<string | null>(null);

  function handleDriveChange(val: string) {
    router.push(`/placement/applications?driveId=${val}`);
  }

  async function handleStatusChange(appId: string, status: string) {
    setLoadingId(appId);
    await updateApplicationStatus(appId, status);
    setLoadingId(null);
    router.refresh();
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'applied': return 'default';
      case 'shortlisted': return 'secondary';
      case 'interviewed': return 'outline';
      case 'selected': return 'default'; // Maybe custom green
      case 'rejected': return 'destructive';
      default: return 'default';
    }
  };

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Select a Campus Drive</CardTitle>
        </CardHeader>
        <CardContent>
          <Select 
            value={selectedDriveId || ""} 
            onValueChange={handleDriveChange}
          >
            <SelectTrigger className="w-full md:w-[400px]">
              <SelectValue placeholder="Select a drive to view applications" />
            </SelectTrigger>
            <SelectContent>
              {drives.map(drive => (
                <SelectItem key={drive.id} value={drive.id}>
                  {drive.company_name} - {drive.job_role}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </CardContent>
      </Card>

      {selectedDriveId && (
        <div className="rounded-md border bg-card">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Student Name</TableHead>
                <TableHead>Email</TableHead>
                <TableHead>CGPA</TableHead>
                <TableHead>Applied At</TableHead>
                <TableHead>Resume</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Action</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {initialApplications.map((app) => (
                <TableRow key={app.id}>
                  <TableCell className="font-medium">{app.students.users.full_name}</TableCell>
                  <TableCell>{app.students.users.email}</TableCell>
                  <TableCell>{app.students.current_cgpa}</TableCell>
                  <TableCell>{format(new Date(app.applied_at), "PPp")}</TableCell>
                  <TableCell>
                    {app.resume_url ? (
                      <a href={app.resume_url} target="_blank" rel="noreferrer" className="flex items-center text-blue-600 hover:underline">
                        View <ExternalLink className="w-3 h-3 ml-1" />
                      </a>
                    ) : (
                      <span className="text-muted-foreground">N/A</span>
                    )}
                  </TableCell>
                  <TableCell>
                    <Badge variant={getStatusColor(app.status) as any}>
                      {app.status.toUpperCase()}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <Select 
                      disabled={loadingId === app.id}
                      defaultValue={app.status}
                      onValueChange={(val: string) => handleStatusChange(app.id, val)}
                    >
                      <SelectTrigger className="w-[140px]">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="applied">Applied</SelectItem>
                        <SelectItem value="shortlisted">Shortlisted</SelectItem>
                        <SelectItem value="interviewed">Interviewed</SelectItem>
                        <SelectItem value="selected">Selected</SelectItem>
                        <SelectItem value="rejected">Rejected</SelectItem>
                      </SelectContent>
                    </Select>
                  </TableCell>
                </TableRow>
              ))}
              {initialApplications.length === 0 && (
                <TableRow>
                  <TableCell colSpan={7} className="text-center py-6 text-muted-foreground">
                    No applications received for this drive yet.
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </div>
      )}
    </div>
  );
}

import { getUserProfile } from "@/features/auth/user";
import { redirect } from "next/navigation";
import { getPlacements, getPlacementApplications } from "@/features/placement/actions";
import { ApplicationsClient } from "./client";

export default async function ApplicationsPage({ searchParams }: { searchParams: Promise<{ driveId?: string }> }) {
  const profile = await getUserProfile();
  if (!profile || profile.role !== "placement") {
    redirect("/login");
  }

  const { driveId } = await searchParams;
  const { data: drives } = await getPlacements();

  let applications: any[] = [];
  if (driveId) {
    const res = await getPlacementApplications(driveId);
    applications = res.data || [];
  }

  return (
    <div className="flex-1 space-y-6 p-8 pt-6">
      <div className="flex items-center justify-between space-y-2">
        <h2 className="text-3xl font-bold tracking-tight">Manage Applications</h2>
      </div>

      <ApplicationsClient 
        drives={drives || []} 
        initialApplications={applications}
        selectedDriveId={driveId}
      />
    </div>
  );
}

