import { getUserProfile } from "@/features/auth/user";
import { redirect } from "next/navigation";
import { getPlacementKPIs, getPlacements, getPlacementApplications } from "@/features/placement/actions";
import { ReportsClient } from "./client";
import { createClient } from "@/lib/supabase/server";

export default async function PlacementReportsPage() {
  const profile = await getUserProfile();
  if (!profile || profile.role !== "placement") {
    redirect("/login");
  }

  // Fetch complex data for reports (e.g. placements by department)
  // We can do this efficiently using Supabase RPC or just grouping here
  const supabase = await createClient();
  const { data: appsData } = await supabase
    .from("placement_applications")
    .select(`
      status,
      students!inner(
        departments(name)
      )
    `)
    .eq("status", "selected");

  // Aggregate data by department
  const deptCount: Record<string, number> = {};
  appsData?.forEach((app: any) => {
    const deptName = app.students.departments?.name || "Unknown";
    deptCount[deptName] = (deptCount[deptName] || 0) + 1;
  });

  const chartData = Object.keys(deptCount).map(key => ({
    department: key,
    students: deptCount[key]
  }));

  return (
    <div className="flex-1 space-y-6 p-8 pt-6">
      <div className="flex items-center justify-between space-y-2">
        <h2 className="text-3xl font-bold tracking-tight">Placement Reports</h2>
      </div>

      <ReportsClient chartData={chartData} />
    </div>
  );
}

"use client";

import { useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { FileText, CalendarClock, UploadCloud, CheckCircle2, AlertCircle, ExternalLink, Loader2 } from "lucide-react";
import { format, parseISO } from "date-fns";
import { submitAssignment } from "@/features/assignments/actions";
import { toast } from "sonner";
import { Input } from "@/components/ui/input";

export function StudentAssignmentsClient({ 
  studentId, 
  assignments 
}: { 
  studentId: string; 
  assignments: any[];
}) {
  const [activeTab, setActiveTab] = useState("pending");
  const [selectedAssignment, setSelectedAssignment] = useState<any>(null);
  const [isSubmitOpen, setIsSubmitOpen] = useState(false);
  const [file, setFile] = useState<File | null>(null);
  const [uploading, setUploading] = useState(false);

  const handleOpenSubmit = (assignment: any) => {
    setSelectedAssignment(assignment);
    setFile(null);
    setIsSubmitOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) {
      toast.error("Please select a file to submit");
      return;
    }

    setUploading(true);
    const formData = new FormData();
    formData.append("assignment_id", selectedAssignment.id);
    formData.append("student_id", studentId);
    formData.append("file", file);

    const result = await submitAssignment(formData);
    if (result.error) {
      toast.error(result.error);
    } else {
      toast.success("Assignment submitted successfully!");
      setIsSubmitOpen(false);
      window.location.reload();
    }
    setUploading(false);
  };

  const pending = assignments.filter(a => !a.submission && new Date() <= new Date(a.deadline));
  const submitted = assignments.filter(a => !!a.submission);
  const missed = assignments.filter(a => !a.submission && new Date() > new Date(a.deadline));

  const AssignmentCard = ({ a, status }: { a: any, status: "pending" | "submitted" | "missed" }) => {
    const isGraded = a.submission?.marks_obtained !== null && a.submission?.marks_obtained !== undefined;

    return (
      <Card className="flex flex-col h-full hover:shadow-md transition-shadow">
        <CardContent className="p-5 flex flex-col flex-1">
          <div className="flex justify-between items-start mb-3">
            {status === "pending" && <Badge variant="secondary" className="flex items-center"><CalendarClock className="w-3 h-3 mr-1"/> Pending</Badge>}
            {status === "submitted" && <Badge variant="default" className="bg-green-600 hover:bg-green-700 flex items-center"><CheckCircle2 className="w-3 h-3 mr-1"/> Submitted</Badge>}
            {status === "missed" && <Badge variant="destructive" className="flex items-center"><AlertCircle className="w-3 h-3 mr-1"/> Missed</Badge>}

            <span className="text-xs font-bold text-muted-foreground bg-muted px-2 py-1 rounded-md">
              {a.max_marks} Marks
            </span>
          </div>

          <h3 className="font-bold text-lg leading-tight mb-1">{a.title}</h3>
          <div className="text-xs font-medium text-primary mb-3">{a.subject_code} - {a.subject_name}</div>

          {a.description && (
            <p className="text-sm text-muted-foreground line-clamp-2 mb-4">
              {a.description}
            </p>
          )}

          <div className="mt-auto space-y-3">
            <div className="flex justify-between items-center text-xs text-muted-foreground bg-muted/50 p-2 rounded-md">
              <div className="flex flex-col">
                <span className="font-semibold">Deadline</span>
                <span>{format(parseISO(a.deadline), "MMM d, h:mm a")}</span>
              </div>
              {a.file_url && (
                <a href={a.file_url} target="_blank" rel="noreferrer" className="flex items-center text-primary hover:underline">
                  <ExternalLink className="h-3 w-3 mr-1" /> Attached File
                </a>
              )}
            </div>

            {status === "submitted" && (
              <div className="bg-primary/5 p-3 rounded-md border border-primary/20 space-y-2">
                <div className="flex justify-between items-center text-sm">
                  <span className="font-medium">Marks Obtained:</span>
                  {isGraded ? (
                    <span className="font-bold text-lg">{a.submission.marks_obtained} <span className="text-sm text-muted-foreground font-normal">/ {a.max_marks}</span></span>
                  ) : (
                    <span className="text-muted-foreground italic">Pending Review</span>
                  )}
                </div>
                {isGraded && a.submission.feedback && (
                  <div className="text-xs text-muted-foreground border-t border-primary/10 pt-2 mt-2">
                    <span className="font-semibold block mb-1 text-primary">Faculty Feedback:</span>
                    {a.submission.feedback}
                  </div>
                )}
              </div>
            )}

            {status === "pending" && (
              <Button onClick={() => handleOpenSubmit(a)} className="w-full">
                <UploadCloud className="h-4 w-4 mr-2" /> Upload Submission
              </Button>
            )}

            {status === "submitted" && new Date() <= new Date(a.deadline) && (
              <Button onClick={() => handleOpenSubmit(a)} variant="outline" className="w-full">
                <UploadCloud className="h-4 w-4 mr-2" /> Override Submission
              </Button>
            )}
          </div>
        </CardContent>
      </Card>
    );
  };

  return (
    <div className="space-y-6">
      <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
        <TabsList className="grid w-full grid-cols-3 max-w-[400px]">
          <TabsTrigger value="pending">Pending ({pending.length})</TabsTrigger>
          <TabsTrigger value="submitted">Submitted ({submitted.length})</TabsTrigger>
          <TabsTrigger value="missed">Missed ({missed.length})</TabsTrigger>
        </TabsList>

        <TabsContent value="pending" className="pt-6">
          {pending.length === 0 ? (
            <div className="text-center p-12 text-muted-foreground">No pending assignments!</div>
          ) : (
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
              {pending.map(a => <AssignmentCard key={a.id} a={a} status="pending" />)}
            </div>
          )}
        </TabsContent>

        <TabsContent value="submitted" className="pt-6">
          {submitted.length === 0 ? (
            <div className="text-center p-12 text-muted-foreground">You haven't submitted any assignments yet.</div>
          ) : (
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
              {submitted.map(a => <AssignmentCard key={a.id} a={a} status="submitted" />)}
            </div>
          )}
        </TabsContent>

        <TabsContent value="missed" className="pt-6">
          {missed.length === 0 ? (
            <div className="text-center p-12 text-muted-foreground">You haven't missed any assignments. Keep it up!</div>
          ) : (
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
              {missed.map(a => <AssignmentCard key={a.id} a={a} status="missed" />)}
            </div>
          )}
        </TabsContent>
      </Tabs>

      <Dialog open={isSubmitOpen} onOpenChange={setIsSubmitOpen}>
        <DialogContent className="sm:max-w-[425px]">
          <DialogHeader>
            <DialogTitle>Submit Assignment</DialogTitle>
          </DialogHeader>
          <form onSubmit={handleSubmit} className="space-y-4 pt-4">
            <div className="flex flex-col gap-1 mb-4">
              <span className="text-sm font-semibold">{selectedAssignment?.title}</span>
              <span className="text-xs text-muted-foreground">Due: {selectedAssignment?.deadline && format(parseISO(selectedAssignment.deadline), "MMM d, h:mm a")}</span>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">Upload File (PDF, DOCX, ZIP)</label>
              <Input 
                type="file" 
                required
                onChange={(e) => setFile(e.target.files?.[0] || null)} 
              />
              <p className="text-xs text-muted-foreground">Maximum file size: 50MB. Late submissions will be rejected.</p>
            </div>

            <Button type="submit" className="w-full mt-4" disabled={uploading}>
              {uploading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {uploading ? "Uploading..." : "Submit"}
            </Button>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { File, Image as ImageIcon, Link as LinkIcon, FileText, PlayCircle, FileArchive, Download, Search, ExternalLink, Filter } from "lucide-react";
import { format, parseISO } from "date-fns";

export function StudentNotesClient({ initialNotes }: { initialNotes: any[] }) {
  const [search, setSearch] = useState("");
  const [subjectFilter, setSubjectFilter] = useState("");
  const [unitFilter, setUnitFilter] = useState("");

  // Extract unique subjects and units for filters
  const subjects = Array.from(new Set(initialNotes.map(n => n.subject_name))).filter(Boolean);
  const units = Array.from(new Set(initialNotes.map(n => n.unit))).filter(Boolean);

  const filteredNotes = initialNotes.filter(n => {
    const matchesSearch = n.title.toLowerCase().includes(search.toLowerCase()) || 
                          (n.description && n.description.toLowerCase().includes(search.toLowerCase()));
    const matchesSubject = subjectFilter ? n.subject_name === subjectFilter : true;
    const matchesUnit = unitFilter ? n.unit === unitFilter : true;
    return matchesSearch && matchesSubject && matchesUnit;
  });

  const getIcon = (type: string) => {
    switch (type) {
      case "pdf": return <FileText className="h-5 w-5 text-red-500" />;
      case "ppt": return <File className="h-5 w-5 text-orange-500" />;
      case "docx": return <FileText className="h-5 w-5 text-blue-500" />;
      case "zip": return <FileArchive className="h-5 w-5 text-yellow-500" />;
      case "image": return <ImageIcon className="h-5 w-5 text-green-500" />;
      case "youtube": return <PlayCircle className="h-5 w-5 text-red-600" />;
      default: return <LinkIcon className="h-5 w-5 text-blue-400" />;
    }
  };

  return (
    <div className="space-y-6">
      <Card>
        <CardContent className="pt-6">
          <div className="flex flex-col md:flex-row gap-4">
            <div className="relative flex-1">
              <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search materials..."
                className="pl-8"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
            <div className="flex gap-4 w-full md:w-auto">
              <select 
                value={subjectFilter} 
                onChange={e => setSubjectFilter(e.target.value)}
                className="flex h-10 w-full md:w-[200px] rounded-md border border-input bg-background px-3 py-2 text-sm"
              >
                <option value="">All Subjects</option>
                {subjects.map((s: any) => (
                  <option key={s} value={s}>{s}</option>
                ))}
              </select>
              <select 
                value={unitFilter} 
                onChange={e => setUnitFilter(e.target.value)}
                className="flex h-10 w-full md:w-[150px] rounded-md border border-input bg-background px-3 py-2 text-sm"
              >
                <option value="">All Units</option>
                {units.map((u: any) => (
                  <option key={u} value={u}>{u}</option>
                ))}
              </select>
            </div>
          </div>
        </CardContent>
      </Card>

      {filteredNotes.length === 0 ? (
        <Card className="flex flex-col items-center justify-center p-12 text-center bg-muted/30 border-dashed">
          <Search className="h-12 w-12 text-muted-foreground/30 mb-4" />
          <h3 className="text-lg font-semibold text-muted-foreground">No materials found</h3>
          <p className="text-muted-foreground text-sm max-w-sm mt-1">Try adjusting your filters or search query.</p>
        </Card>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
          {filteredNotes.map(note => (
            <Card key={note.id} className="flex flex-col h-full hover:shadow-md transition-shadow group relative overflow-hidden">
              <div className="absolute inset-x-0 top-0 h-1 bg-gradient-to-r from-primary/20 to-primary/40 opacity-0 group-hover:opacity-100 transition-opacity"></div>
              <CardContent className="p-5 flex flex-col flex-1">
                <div className="flex justify-between items-start mb-3">
                  <div className="flex items-center gap-2 bg-muted px-2 py-1 rounded-md text-xs font-semibold uppercase">
                    {getIcon(note.resource_type)}
                    <span>{note.resource_type}</span>
                  </div>
                  {note.unit && <Badge variant="outline">{note.unit}</Badge>}
                </div>

                <h3 className="font-bold text-lg leading-tight mb-1 line-clamp-2" title={note.title}>{note.title}</h3>
                <div className="text-xs font-medium text-primary mb-2">{note.subject_code} - {note.subject_name}</div>

                {note.description && (
                  <p className="text-sm text-muted-foreground line-clamp-3 mb-4 flex-1">
                    {note.description}
                  </p>
                )}

                <div className="mt-auto pt-4 flex items-center justify-between border-t border-border/50">
                  <div className="flex flex-col">
                    <span className="text-xs text-muted-foreground">{format(parseISO(note.created_at), "MMM d, yyyy")}</span>
                    <span className="text-[10px] text-muted-foreground/70">{note.faculty_name}</span>
                  </div>
                  <a href={note.url} target="_blank" rel="noreferrer" className="inline-flex items-center justify-center rounded-md text-sm font-medium transition-colors bg-primary text-primary-foreground hover:bg-primary/90 h-9 px-3 gap-2">
                    {["link", "youtube"].includes(note.resource_type) ? (
                      <><ExternalLink className="h-4 w-4" /> Open</>
                    ) : (
                      <><Download className="h-4 w-4" /> View</>
                    )}
                  </a>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { applyToPlacement } from "@/features/placement/actions";
import { createClient } from "@/lib/supabase/client";
import { Card, CardContent, CardHeader, CardTitle, CardDescription, CardFooter } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Building2, Calendar, MapPin, DollarSign, GraduationCap } from "lucide-react";
import { format, isPast } from "date-fns";
import { toast } from "sonner";

export function StudentPlacementsClient({ 
  placements,
  studentId
}: { 
  placements: any[],
  studentId: string
}) {
  const [selectedPlacement, setSelectedPlacement] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [file, setFile] = useState<File | null>(null);

  const supabase = createClient();

  async function handleApply(e: React.FormEvent) {
    e.preventDefault();
    if (!file || !selectedPlacement) return;

    setLoading(true);

    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${studentId}/${selectedPlacement.id}_${Date.now()}.${fileExt}`;
      const { data: uploadData, error: uploadError } = await supabase.storage
        .from('resumes')
        .upload(fileName, file, { upsert: true });

      if (uploadError) throw new Error(uploadError.message);

      const { data: { publicUrl } } = supabase.storage
        .from('resumes')
        .getPublicUrl(fileName);

      const res = await applyToPlacement(selectedPlacement.id, studentId, publicUrl);
      if (res.error) throw new Error(res.error);

      toast.success("Application submitted successfully!");
      setSelectedPlacement(null);
      window.location.reload();
    } catch (err: any) {
      toast.error(err.message || "Failed to submit application");
    } finally {
      setLoading(false);
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'applied': return 'default';
      case 'shortlisted': return 'secondary';
      case 'interviewed': return 'outline';
      case 'selected': return 'default';
      case 'rejected': return 'destructive';
      default: return 'default';
    }
  };

  return (
    <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
      {placements.map((drive) => {
        const isClosed = isPast(new Date(drive.application_deadline));
        const hasApplied = !!drive.application;

        return (
          <Card key={drive.id} className="flex flex-col">
            <CardHeader>
              <div className="flex items-center gap-3">
                <div className="bg-primary/10 p-2 rounded-lg">
                  <Building2 className="w-6 h-6 text-primary" />
                </div>
                <div>
                  <CardTitle className="text-xl">{drive.company_name}</CardTitle>
                  <CardDescription>{drive.job_role}</CardDescription>
                </div>
              </div>
            </CardHeader>
            <CardContent className="flex-1 space-y-4">
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div className="flex items-center gap-2 text-muted-foreground">
                  <Badge variant="outline">{drive.placement_type === 'internship' ? 'Internship' : 'Full-Time'}</Badge>
                </div>
                <div className="flex items-center gap-2 text-muted-foreground">
                  <DollarSign className="w-4 h-4" />
                  <span>{drive.ctc || "Not Disclosed"}</span>
                </div>
                <div className="flex items-center gap-2 text-muted-foreground">
                  <MapPin className="w-4 h-4" />
                  <span>{drive.locations || "Multiple"}</span>
                </div>
                <div className="flex items-center gap-2 text-muted-foreground">
                  <GraduationCap className="w-4 h-4" />
                  <span>Min CGPA: {drive.eligibility_cgpa}</span>
                </div>
                <div className="flex items-center gap-2 text-muted-foreground col-span-2">
                  <Calendar className="w-4 h-4" />
                  <span>Deadline: {format(new Date(drive.application_deadline), "PPP")}</span>
                </div>
              </div>

              {hasApplied && (
                <div className="p-3 bg-muted rounded-md flex items-center justify-between border">
                  <span className="text-sm font-medium">Application Status</span>
                  <Badge variant={getStatusColor(drive.application.status) as any}>
                    {drive.application.status.toUpperCase()}
                  </Badge>
                </div>
              )}
            </CardContent>
            <CardFooter>
              {!hasApplied ? (
                <Dialog open={selectedPlacement?.id === drive.id} onOpenChange={(open) => !open && setSelectedPlacement(null)}>
                  <DialogTrigger asChild>
                    <Button 
                      className="w-full" 
                      disabled={isClosed}
                      onClick={() => setSelectedPlacement(drive)}
                    >
                      {isClosed ? "Applications Closed" : "Apply Now"}
                    </Button>
                  </DialogTrigger>
                  <DialogContent>
                    <DialogHeader>
                      <DialogTitle>Apply to {drive.company_name}</DialogTitle>
                    </DialogHeader>
                    <form onSubmit={handleApply} className="space-y-4">
                      <div className="space-y-2">
                        <Label>Upload Resume (PDF)</Label>
                        <Input 
                          type="file" 
                          accept=".pdf" 
                          required 
                          onChange={(e) => setFile(e.target.files?.[0] || null)}
                        />
                        <p className="text-xs text-muted-foreground">
                          Please ensure your resume is up to date and in PDF format.
                        </p>
                      </div>
                      <Button type="submit" className="w-full" disabled={loading || !file}>
                        {loading ? "Submitting..." : "Submit Application"}
                      </Button>
                    </form>
                  </DialogContent>
                </Dialog>
              ) : (
                <Button variant="secondary" className="w-full" disabled>
                  Already Applied
                </Button>
              )}
            </CardFooter>
          </Card>
        );
      })}

      {placements.length === 0 && (
        <div className="col-span-full text-center py-12 text-muted-foreground border rounded-lg border-dashed">
          No campus drives available at the moment.
        </div>
      )}
    </div>
  );
}

