// Save attendance record
export async function saveAttendanceRecord(
  sectionId: string,
  subjectId: string,
  date: string,
  records: { student_id: string; status: "present" | "absent" | "late" }[]
) {
  try {
    const profile = await getUserProfile();
    if (!profile || profile.role !== "faculty") {
      return { error: "Unauthorized" };
    }

    const supabase = await createClient();

    // 1. Check if attendance already exists
    const { data: existing } = await (supabase as any)
      .from("attendance")
      .select("id")
      .eq("section_id", sectionId)
      .eq("subject_id", subjectId)
      .eq("date", date)
      .single();

    let attendanceId = existing?.id;

    // 2. If not, create it
    if (!attendanceId) {
      const { data: newAttendance, error: createError } = await (supabase as any)
        .from("attendance")
        .insert({
          section_id: sectionId,
          subject_id: subjectId,
          date: date,
          faculty_id: profile.id,
        })
        .select("id")
        .single();

      if (createError) {
        console.error("Error creating attendance session:", createError);
        return { error: createError.message };
      }
      attendanceId = newAttendance.id;
    }

    // 3. Upsert records
    const recordsToInsert = records.map((r) => ({
      attendance_id: attendanceId,
      student_id: r.student_id,
      status: r.status,
    }));

    const { error: upsertError } = await (supabase as any)
      .from("attendance_records")
      .upsert(recordsToInsert, { onConflict: "attendance_id, student_id" });

    if (upsertError) {
      console.error("Error upserting attendance records:", upsertError);
      return { error: upsertError.message };
    }

    revalidatePath("/faculty/attendance");
    return { success: true };
  } catch (error: any) {
    return { error: error.message || "Failed to save attendance" };
  }
}

"use server";

import { createClient } from "@/lib/supabase/server";
import { getUserProfile } from "@/features/auth/user";

export async function getStudentAttendanceAnalytics() {
  try {
    const profile = await getUserProfile();
    if (!profile || profile.role !== "student") {
      return { error: "Unauthorized" };
    }

    const supabase = await createClient();

    // Fetch all attendance records for this student
    const { data: records, error } = await (supabase as any)
      .from("attendance_records")
      .select(`
        status,
        attendance (
          date,
          subject_id,
          subjects (
            name,
            code
          )
        )
      `)
      .eq("student_id", profile.id)
      .order("attendance(date)", { ascending: false });

    if (error) {
      console.error("Error fetching student attendance:", error);
      return { error: error.message };
    }

    // Process analytics
    let totalClasses = 0;
    let presentClasses = 0;
    let lateClasses = 0;
    let absentClasses = 0;

    const subjectStats: Record<string, { subject: string; code: string; total: number; present: number; absent: number; late: number }> = {};
    const recentLogs: any[] = [];

    records.forEach((record: any, index: number) => {
      const subjectId = record.attendance.subject_id;
      const subjectName = record.attendance.subjects.name;
      const subjectCode = record.attendance.subjects.code;
      const status = record.status;
      const date = record.attendance.date;

      totalClasses++;
      if (status === "present") presentClasses++;
      if (status === "late") lateClasses++;
      if (status === "absent") absentClasses++;

      // Subject stats
      if (!subjectStats[subjectId]) {
        subjectStats[subjectId] = { subject: subjectName, code: subjectCode, total: 0, present: 0, absent: 0, late: 0 };
      }
      subjectStats[subjectId].total++;
      if (status === "present") subjectStats[subjectId].present++;
      if (status === "late") subjectStats[subjectId].late++;
      if (status === "absent") subjectStats[subjectId].absent++;

      // Top 5 recent logs
      if (index < 5) {
        recentLogs.push({
          date,
          subject: subjectName,
          status,
        });
      }
    });

    const overallPercentage = totalClasses === 0 ? 100 : Math.round(((presentClasses + lateClasses) / totalClasses) * 100);

    const subjectBreakdown = Object.values(subjectStats).map((s) => ({
      ...s,
      percentage: s.total === 0 ? 100 : Math.round(((s.present + s.late) / s.total) * 100),
    }));

    return {
      data: {
        summary: { totalClasses, presentClasses, lateClasses, absentClasses, overallPercentage },
        subjectBreakdown,
        recentLogs,
      }
    };
  } catch (error: any) {
    return { error: error.message || "Failed to fetch analytics" };
  }
}

"use server";

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { getRoleFromPathname, ROLE_HOME } from "@/config/navigation";
import type { LoginValues } from "@/lib/validations/auth";
import { type AppRole, isDashboardRole } from "@/types/roles";
import { revalidatePath } from "next/cache";

export async function loginAction(values: LoginValues) {
  try {
    const supabase = await createClient();
    const adminClient = createAdminClient();

    // 1. Look up email using the service role key to bypass RLS
    const { data: profile, error: profileError } = await adminClient
      .from("profiles")
      .select("email, role")
      .eq("employee_or_student_id", values.identifier)
      .maybeSingle() as unknown as { data: { email: string; role: AppRole } | null; error: any };

    if (profileError || !profile) {
      return { error: "Invalid credentials." };
    }

    // 2. Sign in with standard Supabase auth
    const { error: signInError } = await supabase.auth.signInWithPassword({
      email: profile.email,
      password: values.password,
    });

    if (signInError) {
      return { error: "Invalid credentials." };
    }

    if (!profile.role || !isDashboardRole(profile.role)) {
      return { error: "Invalid role assigned to user." };
    }

    // 3. Return the destination based on role
    return { destination: ROLE_HOME[profile.role] || "/login" };
  } catch (error) {
    return { error: "An unexpected error occurred." };
  }
}

export async function resetPasswordAction(identifier: string) {
  try {
    const supabase = await createClient();
    const adminClient = createAdminClient();

    const { data: profile, error: profileError } = await adminClient
      .from("profiles")
      .select("email")
      .eq("employee_or_student_id", identifier)
      .maybeSingle() as { data: { email: string } | null; error: any };

    if (profileError || !profile) {
      // Return success anyway to prevent user enumeration
      return { success: true };
    }

    const { error } = await supabase.auth.resetPasswordForEmail(profile.email, {
      redirectTo: `${process.env.NEXT_PUBLIC_SITE_URL || "http://localhost:3000"}/reset-password`,
    });

    if (error) {
      console.error(error);
      return { error: "Failed to send reset email. Please try again." };
    }

    return { success: true };
  } catch (error) {
    return { error: "An unexpected error occurred." };
  }
}

export async function logoutAction() {
  const supabase = await createClient();
  await supabase.auth.signOut();
  revalidatePath("/");
}

